begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1005);

-- The compact manifest is the physical 0014 contract. Every entry produces
-- four independent assertions: existence, type, nullability and default.
create temp table expected_0014_columns(table_name text,column_name text,data_type text,not_null boolean,has_default boolean)on commit drop;
insert into expected_0014_columns
select t.key,c->>0,c->>1,(c->>2)::boolean,(c->>3)::boolean
from jsonb_each($json$
{"sales_v2":[["id","uuid",true,true],["organization_id","uuid",true,false],["branch_id","uuid",true,false],["register_id","uuid",true,false],["warehouse_id","uuid",true,false],["shift_id","uuid",true,false],["customer_counterparty_id","uuid",false,false],["document_number","text",true,false],["business_date","date",true,false],["status","text",true,true],["currency_code","character",true,false],["subtotal_amount","numeric",true,false],["discount_amount","numeric",true,true],["tax_amount","numeric",true,true],["total_amount","numeric",true,false],["paid_amount","numeric",true,false],["debt_amount","numeric",true,true],["device_id","uuid",true,false],["local_operation_id","uuid",true,false],["client_created_at","timestamp with time zone",true,false],["posted_by","uuid",true,false],["posted_at","timestamp with time zone",true,true],["reversal_of_id","uuid",false,false],["created_at","timestamp with time zone",true,true]],
"shifts_v2":[["id","uuid",true,true],["organization_id","uuid",true,false],["branch_id","uuid",true,false],["register_id","uuid",true,false],["opened_by","uuid",true,false],["opening_cash_amount","numeric",true,true],["status","text",true,true],["opened_at","timestamp with time zone",true,true],["closed_by","uuid",false,false],["closed_at","timestamp with time zone",false,false],["actual_cash_amount","numeric",false,false],["difference_amount","numeric",false,false],["version","bigint",true,true],["created_at","timestamp with time zone",true,true]],
"held_sales":[["id","uuid",true,true],["organization_id","uuid",true,false],["branch_id","uuid",true,false],["register_id","uuid",true,false],["created_by","uuid",true,false],["cart_payload","jsonb",true,false],["expires_at","timestamp with time zone",true,false],["created_at","timestamp with time zone",true,true],["updated_at","timestamp with time zone",true,true]],
"payments_v2":[["id","uuid",true,true],["organization_id","uuid",true,false],["branch_id","uuid",true,false],["register_id","uuid",true,false],["shift_id","uuid",true,false],["sale_id","uuid",false,false],["sale_return_id","uuid",false,false],["method","text",true,false],["amount","numeric",true,false],["currency_code","character",true,false],["status","text",true,true],["device_id","uuid",true,false],["local_operation_id","uuid",true,false],["reversal_of_id","uuid",false,false],["created_by","uuid",true,false],["created_at","timestamp with time zone",true,true]],
"sale_returns":[["id","uuid",true,true],["organization_id","uuid",true,false],["original_sale_id","uuid",true,false],["register_id","uuid",true,false],["shift_id","uuid",true,false],["document_number","text",true,false],["status","text",true,true],["total_amount","numeric",true,false],["debt_reduction_amount","numeric",true,true],["device_id","uuid",true,false],["local_operation_id","uuid",true,false],["posted_by","uuid",true,false],["posted_at","timestamp with time zone",true,true],["reversal_of_id","uuid",false,false],["created_at","timestamp with time zone",true,true]],
"shift_totals":[["id","uuid",true,true],["organization_id","uuid",true,false],["shift_id","uuid",true,false],["payment_method","text",true,false],["expected_amount","numeric",true,true],["actual_amount","numeric",false,false],["version","bigint",true,true],["updated_at","timestamp with time zone",true,true]],
"sale_lines_v2":[["id","uuid",true,true],["organization_id","uuid",true,false],["sale_id","uuid",true,false],["line_number","integer",true,false],["product_id","uuid",true,false],["product_name_snapshot","text",true,false],["unit_id","uuid",true,false],["unit_name_snapshot","text",true,false],["product_price_id","uuid",true,false],["quantity","numeric",true,false],["unit_factor","numeric",true,false],["base_quantity","numeric",true,false],["unit_sale_price","numeric",true,false],["unit_cost","numeric",true,false],["discount_amount","numeric",true,true],["tax_amount","numeric",true,true],["line_total_amount","numeric",true,false],["created_at","timestamp with time zone",true,true]],
"fiscal_attempts":[["id","uuid",true,true],["organization_id","uuid",true,false],["fiscal_document_id","uuid",true,false],["attempt_number","integer",true,false],["request_hash","text",true,false],["outcome","text",true,false],["response_code","text",false,false],["response_payload","jsonb",false,false],["error_code","text",false,false],["created_at","timestamp with time zone",true,true],["processing_token","uuid",true,false],["completion_hash","text",true,false]],
"fiscal_documents":[["id","uuid",true,true],["organization_id","uuid",true,false],["branch_id","uuid",true,false],["register_id","uuid",true,false],["shift_id","uuid",true,false],["sale_id","uuid",false,false],["sale_return_id","uuid",false,false],["provider_code","text",true,false],["status","text",true,true],["idempotency_key","text",true,false],["external_receipt_id","text",false,false],["fiscal_sign","text",false,false],["processing_token","uuid",false,false],["processing_started_at","timestamp with time zone",false,false],["issued_at","timestamp with time zone",false,false],["created_at","timestamp with time zone",true,true],["updated_at","timestamp with time zone",true,true]],
"sale_return_lines":[["id","uuid",true,true],["organization_id","uuid",true,false],["sale_return_id","uuid",true,false],["original_sale_line_id","uuid",true,false],["quantity","numeric",true,false],["refund_amount","numeric",true,false],["debt_reduction_amount","numeric",true,true],["created_at","timestamp with time zone",true,true]],
"sale_line_batch_allocations":[["id","uuid",true,true],["organization_id","uuid",true,false],["sale_line_id","uuid",true,false],["product_batch_id","uuid",true,false],["quantity","numeric",true,false],["unit_cost","numeric",true,false],["inventory_movement_id","uuid",true,false],["created_at","timestamp with time zone",true,true]]}
$json$::jsonb)t cross join lateral jsonb_array_elements(t.value)c;

select has_table('public',t,t||' exists')from(values('sales_v2'),('sale_lines_v2'),('sale_line_batch_allocations'),('held_sales'),('payments_v2'),('sale_returns'),('sale_return_lines'),('shifts_v2'),('shift_totals'),('fiscal_documents'),('fiscal_attempts'))x(t);
select has_column('public',e.table_name,e.column_name,e.table_name||'.'||e.column_name||' exists')from expected_0014_columns e;
select ok(i.data_type=e.data_type,e.table_name||'.'||e.column_name||' type')from expected_0014_columns e join information_schema.columns i on i.table_schema='public'and i.table_name=e.table_name and i.column_name=e.column_name;
select is(i.is_nullable='NO',e.not_null,e.table_name||'.'||e.column_name||' nullability')from expected_0014_columns e join information_schema.columns i on i.table_schema='public'and i.table_name=e.table_name and i.column_name=e.column_name;
select is(i.column_default is not null,e.has_default,e.table_name||'.'||e.column_name||' default contract')from expected_0014_columns e join information_schema.columns i on i.table_schema='public'and i.table_name=e.table_name and i.column_name=e.column_name;

-- Coexistence, permissions, templates and inventory source extension.
select has_table('public',t,'legacy '||t||' remains')from(values('sales'),('sale_items'),('payments'),('shifts'))x(t);
select is((select count(*)from permissions),53::bigint,'permission registry 53');
select is((select count(*)from permissions where critical),10::bigint,'critical registry ten');
select is((select count(*)from permission_profile_permissions where permission_profile_id='00000000-0000-0000-0000-000000000101'),53::bigint,'owner template 53');
select is((select count(*)from permission_profile_permissions where permission_profile_id='00000000-0000-0000-0000-000000000102'),16::bigint,'seller template 16');
select ok(exists(select 1 from permissions where code='sales.cost.view'and module='sales'and not critical),'sales.cost.view registered');
select ok(exists(select 1 from permission_profile_permissions ppp join permissions p on p.id=ppp.permission_id where ppp.permission_profile_id='00000000-0000-0000-0000-000000000101'and p.code='sales.cost.view'),'owner receives cost permission');
select ok(not exists(select 1 from permission_profile_permissions ppp join permissions p on p.id=ppp.permission_id where ppp.permission_profile_id='00000000-0000-0000-0000-000000000102'and p.code='sales.cost.view'),'seller does not receive cost permission');
select is((select constraints from permission_profile_permissions ppp join permissions p on p.id=ppp.permission_id where p.code='sales.discount'and ppp.permission_profile_id='00000000-0000-0000-0000-000000000101'),' {"max_discount_percent":100}'::jsonb,'owner discount limit 100');
select is((select constraints from permission_profile_permissions ppp join permissions p on p.id=ppp.permission_id where p.code='sales.discount'and ppp.permission_profile_id='00000000-0000-0000-0000-000000000102'),' {"max_discount_percent":0}'::jsonb,'seller discount limit zero');
select ok((select tgenabled='O'from pg_trigger where tgrelid='permissions'::regclass and tgname='v2_permissions_prevent_insert'),'permission insert guard restored');
select throws_ok($$insert into permissions(code,module,description)values('bad.runtime','sales','bad')$$,'P0001','V2_PERMISSION_REGISTRY_MUTATION_FORBIDDEN','runtime registry insert denied');
select set_eq($$select unnest(array['purchase','inventory_document','warehouse_transfer','sale','sale_return'])$$,$$select unnest(array['purchase','inventory_document','warehouse_transfer','sale','sale_return'])$$,'movement sources preserve old and add sales');
select ok(exists(select 1 from pg_indexes where schemaname='public'and tablename='inventory_movements'and indexname='inventory_movements_source_batch_key'and indexdef ilike'%NULLS NOT DISTINCT%'),'movement source identity is batch aware');

-- RLS and browser grant surface for every financial table.
select ok((select relrowsecurity from pg_class where oid=format('public.%I',t)::regclass),t||' RLS enabled')from(values('sales_v2'),('sale_lines_v2'),('sale_line_batch_allocations'),('held_sales'),('payments_v2'),('sale_returns'),('sale_return_lines'),('shifts_v2'),('shift_totals'),('fiscal_documents'),('fiscal_attempts'))x(t);
select ok(not has_table_privilege('anon',format('public.%I',t),'SELECT,INSERT,UPDATE,DELETE'),'anon denied '||t)from(values('sales_v2'),('sale_lines_v2'),('sale_line_batch_allocations'),('held_sales'),('payments_v2'),('sale_returns'),('sale_return_lines'),('shifts_v2'),('shift_totals'),('fiscal_documents'),('fiscal_attempts'))x(t);
select ok(has_table_privilege('authenticated',format('public.%I',t),'SELECT'),'authenticated select through RLS on '||t)from(values('sales_v2'),('sale_lines_v2'),('sale_line_batch_allocations'),('held_sales'),('payments_v2'),('sale_returns'),('sale_return_lines'),('shifts_v2'),('shift_totals'),('fiscal_documents'),('fiscal_attempts'))x(t);
select ok(not has_table_privilege('authenticated',format('public.%I',t),'INSERT,UPDATE,DELETE'),'authenticated writes denied '||t)from(values('sales_v2'),('sale_lines_v2'),('sale_line_batch_allocations'),('held_sales'),('payments_v2'),('sale_returns'),('sale_return_lines'),('shifts_v2'),('shift_totals'),('fiscal_documents'),('fiscal_attempts'))x(t);

-- Public API and internal worker/guard privileges.
select has_function('public',f,args,f||' exists')from(values
 ('v2_effective_discount_limit',array['uuid']),('v2_can_view_sale',array['uuid','uuid','uuid','boolean']),('v2_fiscal_settings_valid',array['jsonb']),
 ('v2_sales_journal',array['uuid','uuid']),('v2_sale_lines_redacted',array['uuid']),('v2_open_shift',array['uuid','uuid','uuid','uuid','numeric','uuid']),('v2_close_shift',array['uuid','uuid','numeric','uuid']),
 ('v2_hold_sale',array['uuid','uuid','uuid','uuid','jsonb','timestamp with time zone','uuid']),('v2_update_held_sale',array['uuid','uuid','uuid','uuid','jsonb','timestamp with time zone','uuid']),('v2_delete_held_sale',array['uuid','uuid']),
 ('v2_post_sale',array['uuid','uuid','uuid','uuid','uuid','uuid','text','date','character','uuid','uuid','timestamp with time zone','jsonb','jsonb','uuid']),('v2_post_sale_return',array['uuid','uuid','text','uuid','uuid','jsonb','jsonb']),
 ('v2_reverse_sale',array['uuid','uuid','text','uuid','uuid','uuid','jsonb']),('v2_reverse_sale_return',array['uuid','uuid','text','uuid','uuid','uuid','jsonb']),('v2_begin_fiscal_attempt',array['uuid']),('v2_complete_fiscal_attempt',array['uuid','uuid','integer','text','text','text','jsonb','text','text','text']))x(f,args);
select ok(has_function_privilege('authenticated',format('public.%I(%s)',f,args),'EXECUTE'),'authenticated executes safe API '||f)from(values
 ('v2_sales_journal','uuid,uuid'),('v2_sale_lines_redacted','uuid'),('v2_open_shift','uuid,uuid,uuid,uuid,numeric,uuid'),('v2_close_shift','uuid,uuid,numeric,uuid'),('v2_hold_sale','uuid,uuid,uuid,uuid,jsonb,timestamptz,uuid'),('v2_post_sale','uuid,uuid,uuid,uuid,uuid,uuid,text,date,character,uuid,uuid,timestamptz,jsonb,jsonb,uuid'),('v2_post_sale_return','uuid,uuid,text,uuid,uuid,jsonb,jsonb'),('v2_reverse_sale','uuid,uuid,text,uuid,uuid,uuid,jsonb'),('v2_reverse_sale_return','uuid,uuid,text,uuid,uuid,uuid,jsonb'))x(f,args);
select ok(not has_function_privilege('authenticated',format('public.%I(%s)',f,args),'EXECUTE'),'authenticated denied internal function '||f)from(values
 ('v2_sales_context_required',''),('v2_sales_append_only',''),('v2_shift_guard',''),('v2_shift_total_guard',''),('v2_sale_graph_guard',''),('v2_payment_guard',''),('v2_fiscal_document_guard',''),('v2_create_fiscal_intent','uuid,uuid,uuid,uuid,uuid,uuid,text,uuid,uuid'),('v2_begin_fiscal_attempt','uuid'),('v2_complete_fiscal_attempt','uuid,uuid,integer,text,text,text,jsonb,text,text,text'))x(f,args);
select ok(has_function_privilege('service_role',format('public.%I(%s)',f,args),'EXECUTE'),'service worker executes '||f)from(values('v2_begin_fiscal_attempt','uuid'),('v2_complete_fiscal_attempt','uuid,uuid,integer,text,text,text,jsonb,text,text,text'))x(f,args);

-- Exact FK targets and deferred allocation movement edge.
select fk_ok('public',src,col,'public',dst,'id',src||'.'||col||' -> '||dst)from(values
 ('shifts_v2','organization_id','organizations'),('shifts_v2','branch_id','branches'),('shifts_v2','register_id','registers'),('shifts_v2','opened_by','organization_memberships'),('shifts_v2','closed_by','organization_memberships'),
 ('shift_totals','shift_id','shifts_v2'),('sales_v2','shift_id','shifts_v2'),('sales_v2','device_id','devices_v2'),('sales_v2','customer_counterparty_id','counterparties'),('sale_lines_v2','sale_id','sales_v2'),('sale_lines_v2','product_id','products_v2'),('sale_lines_v2','unit_id','units_v2'),('sale_lines_v2','product_price_id','product_prices'),
 ('sale_line_batch_allocations','sale_line_id','sale_lines_v2'),('sale_line_batch_allocations','product_batch_id','product_batches_v2'),('sale_line_batch_allocations','inventory_movement_id','inventory_movements'),('payments_v2','shift_id','shifts_v2'),('payments_v2','sale_id','sales_v2'),('payments_v2','sale_return_id','sale_returns'),('payments_v2','device_id','devices_v2'),('payments_v2','reversal_of_id','payments_v2'),
 ('sale_returns','original_sale_id','sales_v2'),('sale_returns','shift_id','shifts_v2'),('sale_returns','device_id','devices_v2'),('sale_returns','reversal_of_id','sale_returns'),('sale_return_lines','sale_return_id','sale_returns'),('sale_return_lines','original_sale_line_id','sale_lines_v2'),('fiscal_documents','sale_id','sales_v2'),('fiscal_documents','sale_return_id','sale_returns'),('fiscal_attempts','fiscal_document_id','fiscal_documents'))x(src,col,dst);
select ok((select condeferrable and condeferred from pg_constraint where conrelid='sale_line_batch_allocations'::regclass and contype='f'and pg_get_constraintdef(oid)like'FOREIGN KEY (inventory_movement_id)%'),'allocation movement FK deferred');

-- Check, uniqueness, index and trigger contracts are independently asserted.
select ok(exists(select 1 from pg_constraint pc where pc.conrelid=format('public.%I',t)::regclass and pc.contype='c'and pc.conname=c),c||' exists')from(values
 ('shifts_v2','shifts_v2_opening_check'),('shifts_v2','shifts_v2_status_check'),('shifts_v2','shifts_v2_close_shape_check'),('shift_totals','shift_totals_method_check'),
 ('sales_v2','sales_v2_number_check'),('sales_v2','sales_v2_status_check'),('sales_v2','sales_v2_currency_check'),('sales_v2','sales_v2_amounts_check'),('sale_lines_v2','sale_lines_v2_number_check'),('sale_lines_v2','sale_lines_v2_quantity_check'),('sale_lines_v2','sale_lines_v2_amount_check'),
 ('sale_line_batch_allocations','sale_allocations_quantity_check'),('sale_line_batch_allocations','sale_allocations_cost_check'),('held_sales','held_sales_payload_object_check'),('payments_v2','payments_v2_source_check'),('payments_v2','payments_v2_method_check'),('payments_v2','payments_v2_amount_check'),('payments_v2','payments_v2_currency_check'),('payments_v2','payments_v2_status_check'),
 ('sale_returns','sale_returns_number_check'),('sale_returns','sale_returns_status_check'),('sale_returns','sale_returns_amount_check'),('sale_return_lines','sale_return_lines_quantity_check'),('sale_return_lines','sale_return_lines_amount_check'),('fiscal_documents','fiscal_documents_source_check'),('fiscal_documents','fiscal_documents_provider_check'),('fiscal_documents','fiscal_documents_status_check'),('fiscal_documents','fiscal_documents_processing_check'),('fiscal_documents','fiscal_documents_issued_check'),('fiscal_attempts','fiscal_attempt_number_check'),('fiscal_attempts','fiscal_attempt_outcome_check'),('fiscal_attempts','fiscal_attempt_response_object_check'))x(t,c);
select has_index('public',t,i,i||' exists')from(values
 ('shifts_v2','shifts_v2_one_open_register'),('shifts_v2','shifts_v2_branch_opened_idx'),('sales_v2','sales_v2_one_reversal'),('sales_v2','sales_v2_journal_idx'),('sales_v2','sales_v2_shift_idx'),('held_sales','held_sales_scope_idx'),('held_sales','held_sales_expiry_idx'),('payments_v2','payments_v2_shift_method_idx'),('payments_v2','payments_v2_sale_idx'),('sale_returns','sale_returns_one_reversal'),('inventory_movements','inventory_movements_source_batch_key'))x(t,i);
select has_trigger('public',t,tr,tr||' exists')from(values
 ('shifts_v2','v2_shifts_context'),('shifts_v2','v2_shifts_guard'),('shifts_v2','v2_shifts_delete'),('shift_totals','v2_shift_totals_context'),('shift_totals','v2_shift_totals_guard'),('sales_v2','v2_sales_context'),('sales_v2','v2_sales_guard'),('sales_v2','v2_sales_delete'),('sale_lines_v2','v2_sale_lines_context'),('sale_lines_v2','v2_sale_lines_guard'),('sale_lines_v2','v2_sale_lines_append_only'),('sale_line_batch_allocations','v2_sale_allocations_context'),('sale_line_batch_allocations','v2_sale_allocations_guard'),('sale_line_batch_allocations','v2_sale_allocations_append_only'),('held_sales','v2_held_sales_context'),('payments_v2','v2_payments_context'),('payments_v2','v2_payments_guard'),('payments_v2','v2_payments_append_only'),('sale_returns','v2_returns_context'),('sale_returns','v2_returns_lifecycle'),('sale_return_lines','v2_return_lines_context'),('sale_return_lines','v2_return_lines_append_only'),('fiscal_documents','v2_fiscal_documents_write'),('fiscal_attempts','v2_fiscal_attempts_write'))x(t,tr);

-- Fiscal settings are immutable validation logic with explicit defaults.
select ok(v2_fiscal_settings_valid('{}'),'missing fiscal settings means disabled');
select ok(v2_fiscal_settings_valid('{"fiscal":{"mode":"disabled","provider_code":null,"offline_policy":"reject"}}'),'disabled fiscal shape valid');
select ok(v2_fiscal_settings_valid('{"fiscal":{"mode":"required","provider_code":"ofd","offline_policy":"reject"}}'),'required fiscal shape valid');
select ok(v2_fiscal_settings_valid('{"fiscal":{"mode":"deferred","provider_code":"ofd","offline_policy":"defer"}}'),'deferred fiscal shape valid');
select ok(not v2_fiscal_settings_valid('{"fiscal":{"mode":"required","provider_code":null,"offline_policy":"reject"}}'),'required provider enforced');
select ok(not v2_fiscal_settings_valid('{"fiscal":{"mode":"disabled","provider_code":"ofd","offline_policy":"reject"}}'),'disabled provider rejected');
select ok(not v2_fiscal_settings_valid('{"fiscal":{"mode":"deferred","provider_code":"ofd","offline_policy":"reject"}}'),'deferred policy enforced');
select ok(not v2_fiscal_settings_valid('{"fiscal":{"mode":"disabled","provider_code":null,"offline_policy":"reject","unknown":1}}'),'unknown fiscal key rejected');
select ok((select not convalidated from pg_constraint where conrelid='registers'::regclass and conname='registers_fiscal_settings_check'),'register fiscal check is NOT VALID coexistence constraint');

-- Direct financial writes fail even for the trusted SQL role without command context.
select throws_ok($$insert into shifts_v2(organization_id,branch_id,register_id,opened_by)values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid())$$,'P0001','V2_SALES_COMMAND_CONTEXT_REQUIRED','direct shift insert denied');
select throws_ok($$insert into held_sales(organization_id,branch_id,register_id,created_by,cart_payload,expires_at)values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),'{}',now())$$,'P0001','V2_SALES_COMMAND_CONTEXT_REQUIRED','direct held sale insert denied');

-- Transactional shift smoke test exercises authorization, trusted location,
-- idempotency, projection creation, reconciliation and terminal immutability.
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values
 ('00000000-0000-0000-0000-000000000000','00000000-0000-0000-0000-000000014001','authenticated','authenticated','owner14@test','','now','now','now');
insert into organizations(id,name)values('00000000-0000-0000-0000-000000014101','Org14');
insert into organization_settings(organization_id,currency_code,timezone)values('00000000-0000-0000-0000-000000014101','UZS','Asia/Tashkent');
insert into user_profiles(id,auth_user_id,full_name)values('00000000-0000-0000-0000-000000014201','00000000-0000-0000-0000-000000014001','Owner14');
insert into organization_memberships(id,organization_id,user_profile_id,system_role,status,joined_at)values('00000000-0000-0000-0000-000000014301','00000000-0000-0000-0000-000000014101','00000000-0000-0000-0000-000000014201','owner','active',now());
insert into membership_permission_profiles(membership_id,permission_profile_id,assigned_by)values('00000000-0000-0000-0000-000000014301','00000000-0000-0000-0000-000000000101','00000000-0000-0000-0000-000000014301');
insert into branches(id,organization_id,code,name)values('00000000-0000-0000-0000-000000014401','00000000-0000-0000-0000-000000014101','B14','Branch14');
insert into warehouses(id,organization_id,branch_id,code,name,is_primary)values('00000000-0000-0000-0000-000000014501','00000000-0000-0000-0000-000000014101','00000000-0000-0000-0000-000000014401','W14','Warehouse14',true);
insert into registers(id,organization_id,branch_id,default_warehouse_id,code,name)values('00000000-0000-0000-0000-000000014601','00000000-0000-0000-0000-000000014101','00000000-0000-0000-0000-000000014401','00000000-0000-0000-0000-000000014501','R14','Register14');
insert into devices_v2(id,organization_id,branch_id,register_id,name,device_type,fingerprint_hash,status)values('00000000-0000-0000-0000-000000014701','00000000-0000-0000-0000-000000014101','00000000-0000-0000-0000-000000014401','00000000-0000-0000-0000-000000014601','Device14','desktop','fingerprint-14','trusted');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000014001',true);set local role authenticated;
select lives_ok($$select v2_open_shift('00000000-0000-0000-0000-000000014101','00000000-0000-0000-0000-000000014401','00000000-0000-0000-0000-000000014601','00000000-0000-0000-0000-000000014701',100,'00000000-0000-0000-0000-000000014801')$$,'authorized owner opens trusted-register shift');
select is(v2_open_shift('00000000-0000-0000-0000-000000014101','00000000-0000-0000-0000-000000014401','00000000-0000-0000-0000-000000014601','00000000-0000-0000-0000-000000014701',100,'00000000-0000-0000-0000-000000014801'),(select id from shifts_v2 where register_id='00000000-0000-0000-0000-000000014601'),'open replay returns same shift');
