select is((select on_hand_quantity from inventory_balances where batch_id is null and warehouse_id='00000000-0000-0000-0000-000000014501'),10+(select coalesce(sum(quantity_delta),0)from inventory_movements where warehouse_id='00000000-0000-0000-0000-000000014501'), 'aggregate projection equals signed ledger');
select ok((select min(on_hand_quantity)>=0 from inventory_balances where warehouse_id='00000000-0000-0000-0000-000000014501'),'hardening workflows leave no negative balance');
select is((select count(*)from sales),0::bigint,'legacy sales remain untouched');
select is((select count(*)from payments),0::bigint,'legacy payments remain untouched');
select is((select count(*)from shifts),0::bigint,'legacy shifts remain untouched');
select ok(exists(select 1 from inventory_movements where movement_type='sale_return_reversal'and reversal_of_id is not null),'return reversal ledger is linked');
select ok(not exists(select 1 from sale_returns where reversal_of_id is not null and status<>'posted'),'reversal documents retain posted lifecycle');
select ok(not exists(select 1 from sale_return_lines l join sale_returns r on r.id=l.sale_return_id where r.reversal_of_id is not null and l.quantity<=0),'reversal lines preserve positive document quantity');
select ok(not exists(select 1 from payments_v2 p join payments_v2 original on original.id=p.reversal_of_id where p.amount<>-original.amount and p.sale_return_id=(select id from sale_returns where document_number='SR14-1-R')),'opposite payment graph balances exactly');

select * from finish();
rollback;
